def error_rate_by_path(lines):
    total = {}
    errs = {}
    for line in lines:
        _, path, status, _ = parse(line)
        p = normalize(path)
        total[p] = total.get(p, 0) + 1
        if status >= 500:
            errs[p] = errs.get(p, 0) + 1
    return {p: round(errs.get(p,0)/total[p], 4) for p in sorted(total)}
```

